import{_ as r,W as n,N as s,k as o,h as t,o as a,p as l,n as d}from"./chunks/framework.CP1bd6yz.js";const v=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),c={name:"guide/introduction.md"},h={id:"introduction",tabindex:"-1"};function u(p,e,m,g,f,y){const i=n("Badge");return s(),o("div",null,[t("h1",h,[e[0]||(e[0]=a("Introduction ",-1)),l(i,{type:"warning",text:"beta"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#introduction","aria-label":"Permalink to “Introduction”"},"​",-1))]),e[3]||(e[3]=d('<p>Order Lifecycle is a Craft Commerce plugin that tracks and visualises every event in an order&#39;s journey, from cart creation right through to final payment.</p><blockquote><p><strong>Beta Release</strong> - This plugin is still in beta, so APIs, database schema, and behaviour may change between releases. Best not to run it in production without giving it a proper test in your own environment first. If you hit a bug or something doesn&#39;t behave as expected, please <a href="https://github.com/john-henry/craft-order-lifecycle/issues" target="_blank" rel="noreferrer">open an issue</a> - feedback at this stage genuinely shapes what the stable release looks like.</p></blockquote><h2 id="what-is-order-lifecycle" tabindex="-1">What is Order Lifecycle? <a class="header-anchor" href="#what-is-order-lifecycle" aria-label="Permalink to “What is Order Lifecycle?”">​</a></h2><p>Order Lifecycle keeps a constant eye on an order&#39;s lifecycle, recording every significant event as it happens, including:</p><ul><li><strong>Cart Events</strong>: Cart creation, line item additions/updates/removals</li><li><strong>Order Events</strong>: Order completion, status changes, payment status</li><li><strong>Customer Events</strong>: Email updates, address changes</li><li><strong>Payment Events</strong>: Transaction attempts, successes, and failures</li><li><strong>Email Events</strong>: Notifications sent and delivery status</li></ul><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to “Key Features”">​</a></h2><h3 id="complete-event-history" tabindex="-1">Complete Event History <a class="header-anchor" href="#complete-event-history" aria-label="Permalink to “Complete Event History”">​</a></h3><p>Every interaction with an order gets recorded with full context, including timestamps and state snapshots.</p><h3 id="visual-timeline" tabindex="-1">Visual Timeline <a class="header-anchor" href="#visual-timeline" aria-label="Permalink to “Visual Timeline”">​</a></h3><p>A clear, easy-to-follow timeline view shows all events in chronological order, with visual indicators for the different event types.</p><h3 id="performance-statistics" tabindex="-1">Performance Statistics <a class="header-anchor" href="#performance-statistics" aria-label="Permalink to “Performance Statistics”">​</a></h3><p>Metrics are calculated automatically, showing:</p><ul><li>Time from cart creation to order completion</li><li>Payment processing duration</li><li>Order fulfillment timing</li></ul><h3 id="detailed-snapshots" tabindex="-1">Detailed Snapshots <a class="header-anchor" href="#detailed-snapshots" aria-label="Permalink to “Detailed Snapshots”">​</a></h3><p>Each event captures the complete state at that moment, which makes it easy to:</p><ul><li>Debug payment issues</li><li>Understand customer behavior</li><li>Analyze order flow problems</li><li>Audit changes</li></ul><h3 id="ai-insights" tabindex="-1">AI Insights <a class="header-anchor" href="#ai-insights" aria-label="Permalink to “AI Insights”">​</a></h3><p>On-demand Claude-powered analysis for individual orders and store-wide metrics. Click a button on any order to get a plain-language summary of friction points, payment behaviour, and anomalies. The store-level dashboard widget covers conversion rates, abandonment, email reliability, and more, across a configurable date range.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Use Cases”">​</a></h2><ul><li><strong>Debugging</strong>: Quickly work out where orders fail or get stuck</li><li><strong>Analytics</strong>: Get a proper handle on your order funnel and conversion rates</li><li><strong>Customer Support</strong>: See exactly what happened with a customer&#39;s order</li><li><strong>Compliance</strong>: Keep detailed audit trails for all order activities</li><li><strong>Optimization</strong>: Spot the bottlenecks in your checkout process</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><a href="/order-lifecycle/guide/installation.html">Installation Guide</a></li><li><a href="/order-lifecycle/guide/configuration.html">Configuration</a></li><li><a href="/order-lifecycle/guide/performance.html">Performance</a></li><li><a href="/order-lifecycle/guide/event-tracking.html">Event Tracking</a></li><li><a href="/order-lifecycle/guide/ai-insights.html">AI Insights</a></li></ul>',22))])}const k=r(c,[["render",u]]);export{v as __pageData,k as default};
